/**
 * Domain types and the boundary that turns `data/tarjetas.json`
 * (Spanish keys, generated by `scripts/calcular.py --json`) into them.
 */

export type Moment = "breakfast" | "lunch" | "snack" | "dinner";

export const MOMENTS: readonly Moment[] = ["breakfast", "lunch", "snack", "dinner"];

export const MOMENT_LABELS: Record<Moment, string> = {
  breakfast: "Desayuno",
  lunch: "Almuerzo",
  snack: "Merienda",
  dinner: "Cena",
};

export interface Nutrition {
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
}

export interface Goal {
  daily: Nutrition & { fiberMin: number };
  moments: Record<Moment, Nutrition>;
}

/** "dulce" / "salado". Shown only on breakfast and snack Cards. */
export type CardKind = "sweet" | "savory";

export const KIND_LABELS: Record<CardKind, string> = { sweet: "Dulce", savory: "Salado" };

export interface Ingredient {
  id: string;
  name: string;
  grams: number;
  category: string;
  /**
   * The grams in household units ("2 rebanadas", "½ cucharada sopera"), precomputed by
   * `scripts/calcular.py --json`. Absent when the ingredient has no unit or it isn't a multiple of ¼.
   */
  householdUnit?: string;
}

export interface Card {
  id: string;
  moment: Moment;
  kind: CardKind;
  name: string;
  ingredients: Ingredient[];
  preparation: string;
  nutrition: Nutrition & { fiber: number };
}

export interface Catalog {
  goal: Goal;
  /** Cards per Moment, in file order. */
  cards: Record<Moment, Card[]>;
}

// --- `data/tarjetas.json` shape ---

type FileMoment = "desayuno" | "almuerzo" | "merienda" | "cena";

interface FileNutrition {
  kcal: number;
  prot: number;
  carb: number;
  grasa: number;
}

export interface CardsFileCard {
  id: string;
  momento: string;
  tipo: string;
  nombre: string;
  ingredientes: { id: string; g: number; nombre: string; categoria: string; unidad_casera?: string }[];
  preparacion: string;
  nutricion: FileNutrition & { fibra: number };
}

export interface CardsFile {
  objetivos: {
    diario: FileNutrition & { fibra_min: number };
    tolerancia: { kcal_pct: number; macro_g: number };
    momentos: Record<FileMoment, FileNutrition>;
  };
  tarjetas: CardsFileCard[];
}

const FILE_MOMENTS: Record<Moment, FileMoment> = {
  breakfast: "desayuno",
  lunch: "almuerzo",
  snack: "merienda",
  dinner: "cena",
};

function toNutrition(n: FileNutrition): Nutrition {
  return { kcal: n.kcal, protein: n.prot, carbs: n.carb, fat: n.grasa };
}

const MOMENT_BY_FILE_MOMENT = Object.fromEntries(
  MOMENTS.map((moment) => [FILE_MOMENTS[moment], moment]),
) as Record<string, Moment | undefined>;

const KIND_BY_FILE_KIND: Record<string, CardKind | undefined> = {
  dulce: "sweet",
  salado: "savory",
};

function byMoment<T>(fn: (moment: Moment) => T): Record<Moment, T> {
  return Object.fromEntries(MOMENTS.map((moment) => [moment, fn(moment)])) as Record<Moment, T>;
}

function toCard(card: CardsFileCard, moment: Moment): Card {
  return {
    id: card.id,
    moment,
    kind: KIND_BY_FILE_KIND[card.tipo] ?? "savory",
    name: card.nombre,
    ingredients: card.ingredientes.map((i) => ({
      id: i.id,
      name: i.nombre,
      grams: i.g,
      category: i.categoria,
      ...(i.unidad_casera ? { householdUnit: i.unidad_casera } : {}),
    })),
    preparation: card.preparacion,
    nutrition: { ...toNutrition(card.nutricion), fiber: card.nutricion.fibra },
  };
}

export function parseCatalog(file: CardsFile): Catalog {
  const { diario, momentos } = file.objetivos;
  const cards = byMoment<Card[]>(() => []);
  for (const fileCard of file.tarjetas) {
    const moment = MOMENT_BY_FILE_MOMENT[fileCard.momento];
    if (moment) cards[moment].push(toCard(fileCard, moment));
  }
  return {
    goal: {
      daily: { ...toNutrition(diario), fiberMin: diario.fibra_min },
      moments: byMoment((moment) => toNutrition(momentos[FILE_MOMENTS[moment]])),
    },
    cards,
  };
}
